import 'package:supabase_flutter/supabase_flutter.dart';
import '../models/game_term.dart';
import '../models/quiz_question.dart';

/// Thrown with a message that can be shown to the user.
class QuizException implements Exception {
  final String message;
  const QuizException(this.message);

  @override
  String toString() => message;
}

/// Loads quiz questions: from the ready-made bank in Supabase or generated by AI (Supabase Edge Function).
class QuizQuestionService {
  SupabaseClient get _client => Supabase.instance.client;

  /// Categories available in the question bank (sorted).
  Future<List<String>> getCategories() async {
    try {
      final rows = await _client.from('quiz_questions').select('category');
      final categories = {for (final row in rows) row['category'] as String};
      return categories.toList()..sort();
    } catch (_) {
      throw const QuizException('Could not load categories. Is the quiz question bank set up in Supabase?');
    }
  }

  /// Random questions from the bank. [category] and [difficulty] are optional filters.
  Future<List<QuizQuestion>> fromBank({String? category, int? difficulty, required int count}) async {
    try {
      var query = _client.from('quiz_questions').select();
      if (category != null) query = query.eq('category', category);
      if (difficulty != null) query = query.eq('difficulty', difficulty);

      final rows = await query;
      final questions = rows.map(QuizQuestion.tryParse).whereType<QuizQuestion>().toList()..shuffle();
      if (questions.isEmpty) throw const QuizException('No questions found for these settings.');
      return questions.take(count).toList();
    } on QuizException {
      rethrow;
    } catch (_) {
      throw const QuizException('Could not load questions. Check your connection.');
    }
  }

  /// The whole question bank (used by the daily quiz, which picks its questions by the date).
  Future<List<QuizQuestion>> allFromBank() async {
    try {
      final rows = await _client.from('quiz_questions').select();
      return rows.map(QuizQuestion.tryParse).whereType<QuizQuestion>().toList();
    } catch (_) {
      throw const QuizException('Could not load questions. Is the quiz question bank set up in Supabase?');
    }
  }

  /// Categories of the "Closest Match" term bank (sorted).
  Future<List<String>> getTermCategories() async {
    try {
      final rows = await _client.from('closest_terms').select('category');
      final categories = {for (final row in rows) row['category'] as String};
      return categories.toList()..sort();
    } catch (_) {
      throw const QuizException('Could not load categories. Is the term bank set up in Supabase?');
    }
  }

  /// Random terms from the bank for the "Closest Match" mode.
  Future<List<GameTerm>> termsFromBank({String? category, required int count}) async {
    try {
      var query = _client.from('closest_terms').select();
      if (category != null) query = query.eq('category', category);

      final rows = await query;
      final terms = rows.map(GameTerm.tryParse).whereType<GameTerm>().toList()..shuffle();
      if (terms.isEmpty) throw const QuizException('No terms found for these settings.');
      return terms.take(count).toList();
    } on QuizException {
      rethrow;
    } catch (_) {
      throw const QuizException('Could not load terms. Check your connection.');
    }
  }

  /// Terms with definitions about [topic] generated by AI (Edge Function `generate-questions`, kind "terms").
  Future<List<GameTerm>> generateTermsWithAi({required String topic, required int difficulty, required int count}) async {
    try {
      final response = await _client.functions.invoke(
        'generate-questions',
        body: {'kind': 'terms', 'topic': topic, 'difficulty': difficulty, 'count': count},
      );

      final data = response.data;
      final items = data is Map ? data['terms'] : null;
      final terms = items is List ? items.map(GameTerm.tryParse).whereType<GameTerm>().toList() : <GameTerm>[];
      if (terms.isEmpty) throw const QuizException('The AI did not return any usable terms. Try again.');
      return terms.take(count).toList();
    } on QuizException {
      rethrow;
    } on FunctionException catch (e) {
      final details = e.details;
      final message = details is Map && details['error'] is String ? details['error'] as String : null;
      throw QuizException(message ?? 'AI generation is not available right now.');
    } catch (_) {
      throw const QuizException('AI generation failed. Check your connection.');
    }
  }

  /// Questions about [topic] generated by AI (Edge Function `generate-questions`).
  Future<List<QuizQuestion>> generateWithAi({required String topic, required int difficulty, required int count}) async {
    try {
      final response = await _client.functions.invoke(
        'generate-questions',
        body: {'topic': topic, 'difficulty': difficulty, 'count': count},
      );

      final data = response.data;
      final items = data is Map ? data['questions'] : null;
      final questions = items is List ? items.map(QuizQuestion.tryParse).whereType<QuizQuestion>().toList() : <QuizQuestion>[];
      if (questions.isEmpty) throw const QuizException('The AI did not return any usable questions. Try again.');
      return questions.take(count).toList();
    } on QuizException {
      rethrow;
    } on FunctionException catch (e) {
      final details = e.details;
      final message = details is Map && details['error'] is String ? details['error'] as String : null;
      throw QuizException(message ?? 'AI question generation is not available right now.');
    } catch (_) {
      throw const QuizException('AI question generation failed. Check your connection.');
    }
  }
}
